import { sortSizes } from "@/lib/sizes";

export const getProduct = (code: string) => {
  const p = products.find(p => p.code === code);
  if (!p) return p;
  return { ...p, sizes: sortSizes(p.sizes) };
};
export const getVariant = (product: Product, size: string, color: string) =>
  product.variants.find(v => v.size === size && v.color.toLowerCase() === color.toLowerCase());
